import{_ as o,a,b as r}from"./chunks/6.C90syIqY.js";import{_ as l,a as i,b as e,c as s,d as n,e as d,f as c}from"./chunks/16.CEuEpGbu.js";import{_ as p}from"./chunks/17.CpKVWXAe.js";import{_ as h,o as g,c as u,a0 as b}from"./chunks/framework.DRjqbEpm.js";const S=JSON.parse('{"title":"🎛️ 控制面板（Dashboard）詳解","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dashboard.md","filePath":"guide/dashboard.md"}'),m={name:"guide/dashboard.md"};function k(f,t,q,P,v,_){return g(),u("div",null,[...t[0]||(t[0]=[b('<h1 id="🎛️-控制面板-dashboard-詳解" tabindex="-1">🎛️ 控制面板（Dashboard）詳解 <a class="header-anchor" href="#🎛️-控制面板-dashboard-詳解" aria-label="Permalink to &quot;🎛️ 控制面板（Dashboard）詳解&quot;">​</a></h1><p>V-Train 的控制面板是您管理所有設定的核心樞紐——就像是一架飛機的駕駛艙，所有的開關、儀表、按鈕都在這裡！本頁將逐一說明每個功能區塊的用途與操作方式。</p><blockquote><p><img src="'+o+'" alt="控制面板主畫面"></p></blockquote><div class="info custom-block"><p class="custom-block-title">📋 如何開啟控制面板？</p><p>點擊 Chrome 工具列上的 <strong>VT 圖示</strong>即可開啟。如果您已設定密碼鎖，需要先輸入密碼才能進入。</p></div><hr><h2 id="一、面板總覽" tabindex="-1">一、面板總覽 <a class="header-anchor" href="#一、面板總覽" aria-label="Permalink to &quot;一、面板總覽&quot;">​</a></h2><p>控制面板從上到下可以分為以下幾個主要區塊：</p><table tabindex="0"><thead><tr><th>區塊</th><th>主要功能</th></tr></thead><tbody><tr><td>🔴 狀態區</td><td>自動監控(Monitoring)/手動暫停(Monitoring Off)切換</td></tr><tr><td>⚙️ 開關設定區</td><td>互動面板、監控小黑窗、進度條顏色、語言</td></tr><tr><td>🌐 授權按鈕</td><td>授權當前網站</td></tr><tr><td>📊 統計資訊</td><td>已記錄影片數量</td></tr><tr><td>🗂️ 功能快捷區</td><td>規則管理、書籤庫、備份、Pro 升級</td></tr><tr><td>🔒 隱私設定區</td><td>密碼鎖、清除資料</td></tr></tbody></table><hr><h2 id="二、狀態區-自動監控-monitoring-手動暫停-monitoring-off-切換" tabindex="-1">二、狀態區：自動監控(Monitoring) / 手動暫停(Monitoring Off)切換 <a class="header-anchor" href="#二、狀態區-自動監控-monitoring-手動暫停-monitoring-off-切換" aria-label="Permalink to &quot;二、狀態區：自動監控(Monitoring) / 手動暫停(Monitoring Off)切換&quot;">​</a></h2><p>這是面板最重要的開關之一，控制著 V-Train 是否正在「工作」。</p><blockquote><p><img src="'+a+'" alt="監控狀態開關"></p></blockquote><h3 id="自動監控-monitoring" tabindex="-1">自動監控(Monitoring) <a class="header-anchor" href="#自動監控-monitoring" aria-label="Permalink to &quot;自動監控(Monitoring)&quot;">​</a></h3><ul><li>開關打開 → 綠色指示燈亮起，文字顯示「自動監控(Monitoring)」</li><li>V-Train 正在追蹤您的觀看進度</li><li>進度條會顯示在影片縮圖下方</li></ul><h3 id="手動暫停-monitoring-off" tabindex="-1">手動暫停(Monitoring Off) <a class="header-anchor" href="#手動暫停-monitoring-off" aria-label="Permalink to &quot;手動暫停(Monitoring Off)&quot;">​</a></h3><ul><li>開關關閉 → 灰色指示燈，按鈕顯示「手動暫停(Monitoring Off)」</li><li>V-Train 靜默運作，<strong>不記錄、不顯示</strong>任何進度條</li><li>就像「無痕模式的無痕模式」，什麼痕跡都不留</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 什麼時候該用手動暫停(Monitoring Off)？</p><p>當您想看一些不想被紀錄的內容時，切換到手動暫停(Monitoring Off)就對了！開關隨時可以切換，非常方便。</p></div><div class="warning custom-block"><p class="custom-block-title">⚠️ 新安裝預設為手動暫停(Monitoring Off)</p><p>剛安裝完 V-Train，<strong>手動暫停(Monitoring Off)是預設開啟的</strong>。如果您發現安裝後進度條沒有出現，請先確認是否已將開關切到「自動監控(Monitoring)」狀態。</p></div><hr><h2 id="三、開關設定區" tabindex="-1">三、開關設定區 <a class="header-anchor" href="#三、開關設定區" aria-label="Permalink to &quot;三、開關設定區&quot;">​</a></h2><h3 id="🖱️-互動面板開關-hover-panel-show-interaction" tabindex="-1">🖱️ 互動面板開關（Hover Panel / Show Interaction） <a class="header-anchor" href="#🖱️-互動面板開關-hover-panel-show-interaction" aria-label="Permalink to &quot;🖱️ 互動面板開關（Hover Panel / Show Interaction）&quot;">​</a></h3><p>控制在影片播放頁面，畫面上是否要顯示那個半透明的「浮動互動面板」。</p><p>這個小面板提供了：</p><ul><li><strong>👍 喜歡 / 👎 不喜歡</strong> — 快速評分</li><li><strong>❤️ 收藏</strong> — 加入書籤庫</li><li><strong>📸 截圖封面</strong> — 截取當前畫面作為影片封面</li></ul><blockquote><p><img src="'+l+'" alt="互動浮動面板"></p></blockquote><p>如果您覺得這個面板礙眼，可以在這裡將它關閉。</p><div class="info custom-block"><p class="custom-block-title">免費版與 Pro 版說明</p><p>免費版用戶可使用互動面板的所有按鈕，書籤庫收藏上限為 <strong>100 部影片</strong>。升級 Pro 版後收藏數量與觀看紀錄一樣無上限。</p></div><hr><h3 id="🖥️-監控小黑窗-monitor-panel" tabindex="-1">🖥️ 監控小黑窗（Monitor Panel） <a class="header-anchor" href="#🖥️-監控小黑窗-monitor-panel" aria-label="Permalink to &quot;🖥️ 監控小黑窗（Monitor Panel）&quot;">​</a></h3><p>這是一個給進階用戶的除錯工具。開啟後，畫面的<strong>左下角</strong>會出現一個半透明的黑色小視窗，即時顯示 V-Train 內部的運作狀態：</p><ul><li>目前是否正在紀錄中</li><li>目前偵測到的影片 ID</li><li>目前觀看進度（%）</li></ul><blockquote><p><img src="'+i+'" alt="監控小黑窗"></p></blockquote><p>一般使用者不需要開啟這個功能。如果進度條行為異常，開啟小黑窗可以幫助您（或我們的支援人員）快速診斷問題所在。</p><div class="tip custom-block"><p class="custom-block-title">💡 什麼時候有用？</p><p>當您在訓練新網站、規則怎麼設都不對的時候，開啟監控小黑窗，可以即時看到系統抓到了哪個 ID，非常有助於除錯！</p></div><hr><h3 id="🎨-進度條顏色-progress-bar-color" tabindex="-1">🎨 進度條顏色（Progress Bar Color） <a class="header-anchor" href="#🎨-進度條顏色-progress-bar-color" aria-label="Permalink to &quot;🎨 進度條顏色（Progress Bar Color）&quot;">​</a></h3><p>覺得預設的<strong>紅色</strong>進度條看膩了？點擊顏色方塊，就會彈出系統色彩選擇器，讓您挑選任何喜歡的顏色！</p><blockquote><p><img src="'+e+'" alt="進度條顏色選擇器"></p></blockquote><ul><li>您挑選的顏色會即時儲存</li><li>所有已訓練網站的進度條都會套用這個顏色</li><li>想換回紅色？在選色器輸入 <code>#ff0000</code> 即可</li></ul><hr><h3 id="🌐-語言選擇-language-select" tabindex="-1">🌐 語言選擇（Language Select） <a class="header-anchor" href="#🌐-語言選擇-language-select" aria-label="Permalink to &quot;🌐 語言選擇（Language Select）&quot;">​</a></h3><p>面板底部的語言下拉選單，目前說明手冊支援：</p><table tabindex="0"><thead><tr><th>選項</th><th>語言</th></tr></thead><tbody><tr><td><code>zh-TW</code></td><td>繁體中文</td></tr><tr><td><code>en</code></td><td>English</td></tr></tbody></table><p>切換後，面板上所有的文字標籤、按鈕、提示訊息都會即時更新，不需要重新整理。語言設定會被記住，下次開啟面板時自動套用。</p><div class="info custom-block"><p class="custom-block-title">多語言支援</p><p>擴充功能本身支援多國語言，說明手冊目前以中文版為主，英文版為輔，其他語言的手冊將陸續補充。</p></div><hr><h2 id="四、授權當前網站按鈕" tabindex="-1">四、授權當前網站按鈕 <a class="header-anchor" href="#四、授權當前網站按鈕" aria-label="Permalink to &quot;四、授權當前網站按鈕&quot;">​</a></h2><blockquote><p><img src="'+r+'" alt="授權按鈕"></p></blockquote><p>這個<strong>藍色按鈕</strong>顯示在面板的<strong>最上方</strong>。當您在一個<strong>還沒授權</strong>的網站上時，按鈕顯示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>🔓 授權並啟用(Authorize &amp; Enable Current Site)</span></span></code></pre></div><p>點擊後，Chrome 會彈出系統權限確認視窗，允許後按鈕會變成<strong>綠色</strong>並顯示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✅ 已授權(Site Authorized)</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">📌 V-Train 的授權機制</p><p>V-Train 採用 Chrome 的 <strong>Optional Permissions（可選權限）</strong> 機制，只在您明確允許的網站上工作。這意味著它無法悄悄讀取其他網站的資料——您的隱私完全由您掌控。</p></div><hr><h2 id="五、統計資訊-影片記錄數" tabindex="-1">五、統計資訊：影片記錄數 <a class="header-anchor" href="#五、統計資訊-影片記錄數" aria-label="Permalink to &quot;五、統計資訊：影片記錄數&quot;">​</a></h2><p>面板中間會顯示一個數字，代表 V-Train <strong>已記錄的影片觀看進度總數</strong>。</p><ul><li><strong>免費版</strong>：顯示 <code>{數量} / 200</code>（上限 200 筆）</li><li><strong>Pro 版</strong>：顯示 <code>{數量} / ∞ PRO</code>（無限制，金色文字）</li></ul><p>當免費版接近 200 筆上限時，數字會變成<strong>紅色</strong>提醒您。達到上限後，新的觀看紀錄會自動取代最舊的記錄（滾動替換機制）。</p><hr><h2 id="六、已訓練網站管理-規則管理面板" tabindex="-1">六、已訓練網站管理（規則管理面板） <a class="header-anchor" href="#六、已訓練網站管理-規則管理面板" aria-label="Permalink to &quot;六、已訓練網站管理（規則管理面板）&quot;">​</a></h2><p>點擊「<strong>已訓練網站（已訓練網站(Trained Sites) / Rules）</strong>」按鈕，會進入一個獨立的規則管理面板。</p><blockquote><p><img src="'+s+'" alt="規則管理面板"></p></blockquote><h3 id="🔍-搜尋功能" tabindex="-1">🔍 搜尋功能 <a class="header-anchor" href="#🔍-搜尋功能" aria-label="Permalink to &quot;🔍 搜尋功能&quot;">​</a></h3><p>面板頂部有一個搜尋框，輸入網站域名（例如：<code>example.com</code>）即可即時篩選。搜尋採用 <strong>200ms 防抖動</strong>設計，輸入時不會每按一個字母就閃爍一次。</p><h3 id="📄-分頁瀏覽" tabindex="-1">📄 分頁瀏覽 <a class="header-anchor" href="#📄-分頁瀏覽" aria-label="Permalink to &quot;📄 分頁瀏覽&quot;">​</a></h3><p>規則列表每頁顯示 <strong>10 筆</strong>，超過 10 個網站時會自動出現頁碼按鈕（上一頁 / 頁碼 / 下一頁）。</p><h3 id="📋-每個規則卡片包含" tabindex="-1">📋 每個規則卡片包含： <a class="header-anchor" href="#📋-每個規則卡片包含" aria-label="Permalink to &quot;📋 每個規則卡片包含：&quot;">​</a></h3><p>點擊網站名稱可以<strong>展開詳情</strong>，看到：</p><ul><li><strong>槽位圓點（Slot Dots）</strong>：最多 4 個訓練槽（Mod 1 ~ Mod 4），紅色 ● 代表已訓練，灰色 ○ 代表空槽</li><li><strong>人類可讀的規則描述</strong>：例如「URL 路徑最後一段」、「Query 參數 <code>vid</code>」、「Hash 片段」等，讓您一眼看懂規則邏輯</li><li><strong>Raw JSON</strong>：點擊可展開原始規則資料（給進階用戶除錯用）</li><li><strong>VT-RULE 序號</strong>：每個規則都有一個可分享的序號</li></ul><blockquote><p><img src="'+n+'" alt="規則詳情卡片"></p></blockquote><h3 id="📤-複製序號-分享規則" tabindex="-1">📤 複製序號（分享規則） <a class="header-anchor" href="#📤-複製序號-分享規則" aria-label="Permalink to &quot;📤 複製序號（分享規則）&quot;">​</a></h3><p>每個規則卡片右下方有一個<strong>橘色的「📋 Share」按鈕</strong>。點擊後，完整的 <code>VT-RULE-Z...</code> 序號就會被複製到您的剪貼簿，可以直接貼給朋友！</p><p>序號格式說明：</p><ul><li><code>VT-RULE-Z...</code> — 新版格式（deflate-raw 壓縮，比舊版短約 35～50%）</li><li><code>VT-RULE-...</code> — 舊版格式（仍然相容，可正常匯入）</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 序號顯示方式</p><p>列表中的序號為了節省空間，只顯示前 24 碼 + <code>...</code> + 末 4 碼。<strong>將滑鼠停留在序號上</strong>，Tooltip 會顯示完整序號。點擊 Share 按鈕一定是複製完整序號，不用擔心！</p></div><h3 id="🗑️-刪除規則" tabindex="-1">🗑️ 刪除規則 <a class="header-anchor" href="#🗑️-刪除規則" aria-label="Permalink to &quot;🗑️ 刪除規則&quot;">​</a></h3><p>每個規則卡片右上方有一個垃圾桶圖示 🗑️。點擊後會跳出確認視窗，確認後即可刪除該網站的規則。</p><div class="warning custom-block"><p class="custom-block-title">⚠️ 刪除後無法復原</p><p>刪除規則前，建議先用「複製序號」把規則備份起來，以防後悔！</p></div><h3 id="📥-匯入規則-兩種方式" tabindex="-1">📥 匯入規則（兩種方式） <a class="header-anchor" href="#📥-匯入規則-兩種方式" aria-label="Permalink to &quot;📥 匯入規則（兩種方式）&quot;">​</a></h3><p><strong>方式一：貼上序號</strong> 在「Rules」面板中，找到序號輸入框，將 <code>VT-RULE-Z...</code> 序號貼入後點擊「<strong>Import</strong>」按鈕。系統會自動解析並儲存。</p><p><strong>方式二：匯入 JSON 檔案</strong> 點擊「<strong>Import File</strong>」按鈕，選取您之前匯出的 <code>VTrain_Rules_XXXX-XX-XX.json</code> 規則檔，系統會將其中的規則合併到現有規則中（不會覆蓋）。</p><div class="info custom-block"><p class="custom-block-title">📌 關於社群規則庫</p><p>沒有在訓練的心情？到 <a href="https://github.com/vtrain-labs/community-rules" target="_blank" rel="noreferrer">GitHub 社群規則庫</a> 看看有沒有好心人已經分享了您想要的網站規則，直接複製序號匯入就搞定！</p></div><hr><h2 id="七、書籤庫入口-bookmark-vault" tabindex="-1">七、書籤庫入口（Bookmark Vault） <a class="header-anchor" href="#七、書籤庫入口-bookmark-vault" aria-label="Permalink to &quot;七、書籤庫入口（Bookmark Vault）&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">👑 Pro 版限定功能</p><p>書籤庫完整功能需要 <strong>V-Train Pro</strong> 版才能使用。</p></div><p>點擊「<strong>📚 Bookmark Vault</strong>」按鈕，會在新分頁開啟一個全螢幕的精美書籤管理介面。</p><blockquote><p><img src="'+d+'" alt="書籤庫主畫面"></p></blockquote><p>書籤庫功能包含：</p><ul><li><strong>資料夾管理</strong>：建立無限層級的子資料夾，右鍵可重新命名、移動、刪除</li><li><strong>書籤卡片</strong>：每個收藏的影片都有封面縮圖、標題、網址</li><li><strong>快速跳轉</strong>：點擊書籤卡片可直接在新分頁開啟播放頁面</li><li><strong>封面更新</strong>：支援自訂截圖封面（透過互動面板的 📸 截圖功能設定）</li></ul><p>想了解書籤庫的完整功能，請參考 <a href="./bookmark-vault.html">書籤庫詳細說明</a>。</p><hr><h2 id="八、備份與還原" tabindex="-1">八、備份與還原 <a class="header-anchor" href="#八、備份與還原" aria-label="Permalink to &quot;八、備份與還原&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">⚠️ 重要！請定期備份！</p><p>V-Train 採用「<strong>零伺服器架構</strong>」——您的所有觀看紀錄、書籤、規則，<strong>全部只存在您自己的電腦裡</strong>。如果瀏覽器重裝或擴充功能被移除，資料將永久消失！</p></div><h3 id="📥-匯出備份-export" tabindex="-1">📥 匯出備份（Export） <a class="header-anchor" href="#📥-匯出備份-export" aria-label="Permalink to &quot;📥 匯出備份（Export）&quot;">​</a></h3><p>點擊「<strong>Export Full Backup (incl. Rules)</strong>」按鈕，會開啟備份中心頁面。您可以選擇要備份的項目：</p><table tabindex="0"><thead><tr><th>備份項目</th><th>說明</th></tr></thead><tbody><tr><td>✅ Core Data（核心資料）</td><td>觀看紀錄、設定、規則、書籤結構</td></tr><tr><td>🖼️ Images（圖片庫）</td><td>手動截圖的封面圖片（通常較大）</td></tr></tbody></table><p>系統會將資料打包下載到您的電腦。如果圖片數量很多，系統會智能分塊打包成多個 <code>images_part_X.json</code> 檔案。</p><h3 id="📤-匯入還原-import" tabindex="-1">📤 匯入還原（Import） <a class="header-anchor" href="#📤-匯入還原-import" aria-label="Permalink to &quot;📤 匯入還原（Import）&quot;">​</a></h3><p>點擊「<strong>Import Full Backup (incl. Rules)</strong>」按鈕，確認後會開啟備份中心的還原頁面。將之前下載的 JSON 備份檔（或整個 ZIP 壓縮包）<strong>拖曳放入</strong>頁面中即可完美還原。</p><p>想了解完整備份流程，請參考 <a href="./backup.html">備份與還原詳細說明</a>。</p><hr><h2 id="九、pro-版升級" tabindex="-1">九、Pro 版升級 <a class="header-anchor" href="#九、pro-版升級" aria-label="Permalink to &quot;九、Pro 版升級&quot;">​</a></h2><p>面板底部有一個 <strong>「⚡ 解鎖Pro(Unlock V-Train Pro)」</strong> 按鈕。</p><blockquote><p><img src="'+c+'" alt="Pro 升級按鈕"></p></blockquote><h3 id="如何升級" tabindex="-1">如何升級？ <a class="header-anchor" href="#如何升級" aria-label="Permalink to &quot;如何升級？&quot;">​</a></h3><ol><li>點擊「<strong>⚡ 解鎖Pro(Unlock V-Train Pro)</strong>」按鈕。</li><li>系統會跳出對話框，提示您輸入授權序號或前往購買頁面。</li><li>點擊「<strong>前往購買(Go to Purchase)</strong>」，會在新分頁開啟 Lemon Squeezy 的結帳頁面（$4.99 USD，一次性付費，終身授權）。</li><li>購買完成後，您會收到一組授權序號（格式：<code>XXXXXXXX-XXXXXXXX-XXXXXXXX-XXXXXXXX</code>）。</li><li>回到面板，再次點擊升級按鈕，貼入您的授權序號後點擊確認。</li><li>驗證成功！面板按鈕會變成<strong>金色 👑</strong>，顯示「Pro 已啟用」。</li></ol><h3 id="pro-版功能一覽" tabindex="-1">Pro 版功能一覽 <a class="header-anchor" href="#pro-版功能一覽" aria-label="Permalink to &quot;Pro 版功能一覽&quot;">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>免費版</th><th>Pro 版</th></tr></thead><tbody><tr><td>觀看紀錄上限</td><td>200 筆（含書籤）</td><td><strong>無限</strong></td></tr><tr><td>書籤庫</td><td>✅ 上限 100 部</td><td>✅ <strong>無限</strong></td></tr><tr><td>影片互動面板（評分、收藏、截圖）</td><td>✅</td><td>✅</td></tr><tr><td>隱私密碼鎖</td><td>❌</td><td>✅</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">📌 免費版書籤與紀錄的關係</p><p>免費版觀看紀錄上限為 200 筆，<strong>書籤佔用同一個額度</strong>。例如您有 100 部書籤影片（永久保留不被 GC 清除），那麼能動態更新進度的影片就只剩 100 筆。</p></div><div class="tip custom-block"><p class="custom-block-title">授權序號儲存在哪裡？</p><p>您的授權序號加密儲存在 Chrome 的本地 storage 中（<code>storedLicenseKey</code>），不會上傳任何個資。如果需要在新裝置啟用，只需重新輸入同一組序號即可。</p></div><hr><h2 id="十、隱私設定區" tabindex="-1">十、隱私設定區 <a class="header-anchor" href="#十、隱私設定區" aria-label="Permalink to &quot;十、隱私設定區&quot;">​</a></h2><h3 id="🔒-設定密碼鎖-設定密碼-setup-passcode" tabindex="-1">🔒 設定密碼鎖（設定密碼(Setup Passcode)） <a class="header-anchor" href="#🔒-設定密碼鎖-設定密碼-setup-passcode" aria-label="Permalink to &quot;🔒 設定密碼鎖（設定密碼(Setup Passcode)）&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">👑 Pro 版限定功能</p><p>密碼鎖功能需要 <strong>V-Train Pro</strong> 版才能設定。</p></div><p>點擊「<strong>🔒 設定密碼(Setup Passcode)</strong>」按鈕後，輸入您想要的密碼（可以是任意字串，例如數字組合 <code>1234</code>）。</p><p>設定後，每次點擊 VT 圖示開啟面板，都需要先輸入密碼才能看到內容。這讓您的觀看紀錄多了一層保護！</p><h4 id="🆘-忘記密碼怎麼辦-救援解鎖" tabindex="-1">🆘 忘記密碼怎麼辦？（救援解鎖） <a class="header-anchor" href="#🆘-忘記密碼怎麼辦-救援解鎖" aria-label="Permalink to &quot;🆘 忘記密碼怎麼辦？（救援解鎖）&quot;">​</a></h4><p>在密碼輸入畫面，點擊「<strong>忘記密碼(Forgot Passcode?)</strong>」按鈕。</p><ol><li>輸入您的 <strong>Pro 授權序號</strong>（當作身份驗證）。</li><li>驗證成功後，密碼鎖會被清除。</li><li>系統會詢問是否要進行一次備份（建議選「是」！）。</li></ol><blockquote><p><img src="'+p+'" alt="密碼救援畫面"></p></blockquote><div class="tip custom-block"><p class="custom-block-title">清除密碼</p><p>想取消密碼鎖？點擊「設定密碼(Setup Passcode)」→ 在密碼輸入框中<strong>什麼都不輸入、直接確認</strong>，密碼鎖就會被移除。</p></div><hr><h3 id="🗑️-清除資料-clear-data" tabindex="-1">🗑️ 清除資料（Clear Data） <a class="header-anchor" href="#🗑️-清除資料-clear-data" aria-label="Permalink to &quot;🗑️ 清除資料（Clear Data）&quot;">​</a></h3><p>點擊「<strong>🗑️ Clear Data</strong>」按鈕，確認後 V-Train 會刪除所有<strong>本地觀看紀錄</strong>。</p><p>清除的內容：</p><ul><li>✅ 所有影片的觀看進度記錄</li><li>✅ IndexedDB 中的書籤與截圖資料</li></ul><p><strong>不會</strong>被清除的內容：</p><ul><li>❌ 您的 Pro 版授權狀態</li><li>❌ 已訓練的網站規則</li><li>❌ 擴充功能的所有設定（語言、進度條顏色等）</li></ul><div class="danger custom-block"><p class="custom-block-title">⚠️ 清除後不可復原！</p><p>觀看紀錄一旦清除，無法還原。如果您希望日後能恢復資料，請<strong>先匯出備份</strong>再清除！</p></div><hr><h2 id="小結" tabindex="-1">小結 <a class="header-anchor" href="#小結" aria-label="Permalink to &quot;小結&quot;">​</a></h2><p>控制面板看起來按鈕很多，但其實只需要記住幾個最常用的操作：</p><ol><li><strong>🟢 Monitoring 開關</strong> — 確保開著，進度條才會出現</li><li><strong>🔓 授權按鈕</strong> — 每個新網站都要按一次</li><li><strong>📋 規則管理</strong> — 查看、分享、匯入訓練規則</li><li><strong>Export Full Backup</strong> — 定期備份，保護您的珍貴紀錄</li></ol><p>有任何疑問，歡迎到 <a href="./faq.html">常見問題（FAQ）</a> 頁面查閱，或至 <a href="https://github.com/vtrain-labs/v-train-extension/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 回報問題！</p>',134)])])}const M=h(m,[["render",k]]);export{S as __pageData,M as default};
